    49          SdkHttpRequest request = context.httpRequest();
    50          String body = null;
    51          if (logRequests) {
    52              if (request.method() == SdkHttpMethod.POST && request instanceof SdkHttpFullRequest sdkHttpFullRequest) {
    53                  try {
    54                      ContentStreamProvider csp = sdkHttpFullRequest.contentStreamProvider().orElse(null);
    55                      if (nonNull(csp)) body = IoUtils.toUtf8String(csp.newStream());
    56                  } catch (IOException e) {
    57                      logger.warn("Unable to obtain request body", e);
    58                  }
    59              }
    60              logger.debug(
    61                      "Request:\n- method: {}\n- url: {}\n- headers: {}\n- query parameters: {}\n- body: {}",
    62                      request.method(),
    63                      request.getUri(),
    64                      request.headers(),
    65                      request.rawQueryParameters(),
    66                      body
    67              );
    68          }
    69      }
