    75          return context.response();
    76      }
    77  
    78      private void logResponse(SdkHttpResponse response, Context.ModifyResponse context) {
    79          if (logResponses) {
    80              logger.debug(
    81                      "Response Status: {} \nHeaders: {} \nResponse Body Type: {}",
    82                      response.statusCode(),
    83                      response.headers(),
    84                      context.response().getClass().getSimpleName());
    85          }
    86      }
