    88      @Override
    89      public Optional<InputStream> modifyHttpResponseContent(
    90              Context.ModifyHttpResponse context, ExecutionAttributes executionAttributes) {
    91          byte[] content = null;
    92          if (logResponses) {
    93              try {
    94                  InputStream responseContentStream = context.responseBody().orElse(InputStream.nullInputStream());
    95                  content = IoUtils.toByteArray(responseContentStream);
    96                  logger.debug("Response Body: {}", new String(content, StandardCharsets.UTF_8));
    97              } catch (IOException e) {
