private static java.util.Map<String, java.util.List<String>> maskHeaders(
        java.util.Map<String, java.util.List<String>> headers) {
    if (headers == null) return null;
    java.util.Map<String, java.util.List<String>> masked = new java.util.LinkedHashMap<>();
    headers.forEach((name, values) -> {
        if ("authorization".equalsIgnoreCase(name) || "x-amz-security-token".equalsIgnoreCase(name)) {
            masked.put(name, java.util.List.of("[REDACTED]"));
        } else {
            masked.put(name, values);
        }
    });
    return masked;
}

